package wordy

import (
	"strconv"
	"strings"
)

// Answer parses a simple math word problem and evaluates it from
// left to right, ignoring the typical order of operations.
// It returns the result and true on success, or 0 and false if the
// question is not a valid word problem.
func Answer(question string) (int, bool) {
	const prefix = "What is "
	if !strings.HasPrefix(question, prefix) || !strings.HasSuffix(question, "?") {
		return 0, false
	}
	tokens := strings.Fields(strings.TrimSuffix(question, "?"))
	// Drop the "What is" prefix tokens, keeping the expression body.
	if len(tokens) < 3 {
		return 0, false
	}
	return evaluate(tokens[2:])
}

// evaluate consumes the expression body: a number followed by any
// number of (operator, number) pairs, in order.
func evaluate(tokens []string) (int, bool) {
	value, ok := number(tokens[0])
	if !ok {
		return 0, false
	}
	for i := 1; i < len(tokens); {
		op, width := operator(tokens[i])
		if width == 0 {
			return 0, false
		}
		if i+width >= len(tokens) {
			return 0, false // operator missing its operand
		}
		operand, ok := number(tokens[i+width])
		if !ok {
			return 0, false
		}
		value, ok = apply(op, value, operand)
		if !ok {
			return 0, false
		}
		i += width + 1
	}
	return value, true
}

// operator reports the operator a token starts and how many tokens it
// spans. It returns 0 if the token is not a known operator.
func operator(tokens ...string) (string, int) {
	switch tokens[0] {
	case "plus":
		return "plus", 1
	case "minus":
		return "minus", 1
	case "multiplied", "divided":
		if len(tokens) < 2 || tokens[1] != "by" {
			return "", 0
		}
		return tokens[0] + " by", 2
	}
	return "", 0
}

func apply(op string, a, b int) (int, bool) {
	switch op {
	case "plus":
		return a + b, true
	case "minus":
		return a - b, true
	case "multiplied by":
		return a * b, true
	case "divided by":
		return a / b, true
	}
	return 0, false
}

func number(token string) (int, bool) {
	n, err := strconv.Atoi(token)
	return n, err == nil
}

